// Reference solution
function undeclaredParams(path, parameters) {
  const inPath = [...path.matchAll(/\{([^}]+)\}/g)].map((m) => m[1]);
  const declared = new Set(parameters.filter((p) => p.in === 'path').map((p) => p.name));
  return inPath.filter((n) => !declared.has(n));
}
